window.RP_SESSION={"id":"S-1e8c237fec7c","messages":[{"id":"RP-II-0149469","time":"2026-08-12T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘는 감자를 삶아서 껍질을 벗기는 것으로 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149470","time":"2026-08-12T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"옆에서는 작은 팬에 베이컨을 굽다가, 베이컨을 잘게 잘라 바싹 구워 기름을 끝까지 뽑아내고.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149471","time":"2026-08-12T03:15:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"삶은 감자를 으깨고 베이컨 기름, 버터, 우유까지 넣고 뜨거울 때 열심히 나무 숟가락으로 섞어둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149472","time":"2026-08-12T03:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하드치즈를 강판에 곱게 갈아서 섞은 뒤에, 소금을 몇 꼬집씩 넣어가며 간을 본다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149473","time":"2026-08-12T03:17:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"적당히 짭짤해서 딱 먹기 좋아져서, 접시에 담아 스푼을 옆에 내놓으면.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149474","time":"2026-08-12T03:17:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"베이컨 매쉬드 포테이토 완성!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149475","time":"2026-08-12T03:18:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"굼떠진 식욕을 부르는 향······","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149476","time":"2026-08-12T03:19:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고소하고 향긋한 향기가 록시를 솔솔 부른다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149477","time":"2026-08-12T03:19:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"후후","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149478","time":"2026-08-12T03:19:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"안 나타나고는 못 배길걸?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149479","time":"2026-08-12T03:20:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"뒷골목 시절 개밥 먹던 시절의 버릇을 애착 인형마냥 버리지 못하던 록시는 자연스레 주방으로 정신을 빼앗긴듯 이끌려 온다···","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149480","time":"2026-08-12T03:20:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"그녀의 향긋한 향이 (다소 의역.)이 나를 부른다···.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149481","time":"2026-08-12T03:20:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 록시 씨, 어, 어서 와요! \"\n\n록시 복복","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149482","time":"2026-08-12T03:20:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 매, 매쉬드 포테이토 드실래요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149483","time":"2026-08-12T03:21:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"독이라도 넣은 건 아니지?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149484","time":"2026-08-12T03:22:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"대놓고 덥석 물어버린다면, 간신히 간판을 세워가던 그녀의 위신이 용납하지 못한다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149485","time":"2026-08-12T03:22:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 그럴리가요! 록시 씨한테 제가 왜 그, 그런 짓을 해요. \"\n\n매쉬드 포테이토를 떠서 입 앞에 스푼을 대어준다.\n\n\" 자, 아 해, 해요, 아. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149486","time":"2026-08-12T03:25:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"흥. 직접 먹어보지 않으면 못 믿겠는걸?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149487","time":"2026-08-12T03:26:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"록시는 대어진 스푼과 레마를 번갈아 보곤 기묘하리만큼 으스스한 만족감에 찬 표정을 지으며, 입을 쫘악 벌린다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149488","time":"2026-08-12T03:26:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"아~\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149489","time":"2026-08-12T03:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"록시의 입에 스푼을 넣어주고 먹기를 기다린다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149490","time":"2026-08-12T03:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 자, 어, 어때요. 맛있죠? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149491","time":"2026-08-12T03:30:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"우물우물 씹으며 풍미를 퍽 느낀다. 이게 정녕 풍족한 삶이란 걸까? \n\n미친 노인네 기저귀 갈아주고 만만한 놈들 지갑이나 훔치던 시절의 록시와는 이제 \"사별\"이다······.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149492","time":"2026-08-12T03:30:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"쩝쩝. 좀 짠데?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149493","time":"2026-08-12T03:30:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"말은 그렇게 해도 맛있게 잘 먹는 록시를 뿌듯하게 바라보며 쓰다듬는다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149494","time":"2026-08-12T03:31:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 마, 많이 먹어요. 요새는 어, 어떻게 지내셨어요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149495","time":"2026-08-12T03:35:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"나쁘고 만만한 새끼들 지갑 좀 털고, 엉덩이를 몇 대 걷어차줬지.\"\n\n밥 먹는듯이 하는 농담. 이젠 그런 시절의 사악한 록시는 이별했으니··· 소일거리나 전전하며 그럭저럭 지내고 있다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149496","time":"2026-08-12T03:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"록시에게 야식을 먹이며 본인도 한 숟갈 떠먹는다","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149497","time":"2026-08-12T03:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맛있어!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149498","time":"2026-08-12T03:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 록시 씨도 파, 파란만장하게 보냈네요. \"\n\n냠냠.\n\n\" 저는 요, 요새 의뢰 어, 없는 동안에는 정말 요리를 자, 자주 한 것 같아요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149499","time":"2026-08-12T03:39:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 도, 돈 많이 벌면 해먹어 보고 싶은 요리가 새, 생겼어요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149500","time":"2026-08-12T03:40:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"엉? 뭔데?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149501","time":"2026-08-12T03:41:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"귀를 쫑긋 열고 경청한다. 이 맹한 녀석의 입맛이 과연 뭘까?","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149502","time":"2026-08-12T03:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 후, 후추 스테이크요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149503","time":"2026-08-12T03:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 질 좋은, 좀 덜 매, 매운 후추를 자, 잔뜩 소고기에 박아서. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149504","time":"2026-08-12T03:44:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 각종 햐, 향신료에 크림에 고급 즈, 증류주로 불까지 붙인 소스 위에 얹는. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149505","time":"2026-08-12T03:44:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아마도... 이 사, 상태로는 평생 벌 돈보다 비, 비쌀 그런 스테이크... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149506","time":"2026-08-12T03:46:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"꽤 거창한 꿈이네.\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149507","time":"2026-08-12T03:46:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"어쩌다 그런 휘황찬란한 걸 먹고 싶어졌대?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149508","time":"2026-08-12T03:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 그야... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149509","time":"2026-08-12T03:47:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 로망이잖아요. 모든 미, 미식가들의. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149510","time":"2026-08-12T03:49:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"풋.\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149511","time":"2026-08-12T03:49:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 비, 비웃지 마요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149512","time":"2026-08-12T03:50:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 만약에 따, 딱 한 명 하고만 같이 먹을 수 있다면... \"\n\n두 사람이 떠오르지만.\n\n\" 록시 씨랑 가, 같이 먹을게요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149513","time":"2026-08-12T03:52:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"흐응. 네 고백은 감사히 받도록 할게!\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149514","time":"2026-08-12T03:53:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"내 유언으로 남겨서 아주 고히 보관해주지······.\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0149515","time":"2026-08-12T03:53:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 고, 고백이 아니구요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149516","time":"2026-08-12T03:53:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마의 얼굴은 이미 빨개서 굳이 빨개질 필요가 없다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149517","time":"2026-08-12T03:53:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"딸기플링","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149518","time":"2026-08-12T03:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-II-0149519","time":"2026-08-12T03:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
